        // pre-existing three-argument overload and the new call passing nodeStatuses:null must
        // produce the exact same document, byte-for-byte — the golden fixtures
        // (examples/hello-guardrails, docs/plans/08-parallel-execution/diagram.html) are out of this
        // task's scope and must not need regenerating.
        string legacy = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
        string newNull = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, nodeStatuses: null);

        Assert.Equal(legacy, newNull);

        // ...and the static path carries NONE of the live-overlay markers. Each of these is absent
        // from today's template, so their absence pins the null path clean — a leak of the feature
        // into the static path (which would silently change every checked-in diagram.html) fails here.
        Assert.DoesNotContain("http-equiv=\"refresh\"", newNull, StringComparison.Ordinal);
        Assert.DoesNotContain("@keyframes", newNull, StringComparison.Ordinal);
        Assert.DoesNotContain("id=\"node-statuses\"", newNull, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatuses_EmitsAMetaRefreshTag()
    {
        // A non-null status map with the default includeRefresh:true is the DURING-RUN diagram — it
        // must carry <meta http-equiv="refresh"> so a plain file:// view re-reads itself as the run
        // progresses (mirrors LogSiteRenderer's during-run index). The static (null) path must not.
        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);
        Assert.Contains("<meta http-equiv=\"refresh\"", live, StringComparison.Ordinal);

        string stat = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, nodeStatuses: null);
        Assert.DoesNotContain("http-equiv=\"refresh\"", stat, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatusesAndIncludeRefreshFalse_OmitsTheMetaRefreshTag()
    {
        // The FINAL settled render (wired at run-end by 06-wire-diagramobserver-into-runcommand):
        // nodeStatuses is STILL non-null (every node shows its final settled status) but
        // includeRefresh:false, so the auto-reload tag is dropped — the page is done refreshing. The
        // status overlay itself must STILL be emitted (the refresh tag and the overlay are independent).
        string settled = HtmlDiagramRenderer.Render(
            Source, Hash, OneTarget, SampleStatuses, includeRefresh: false);

        Assert.DoesNotContain("http-equiv=\"refresh\"", settled, StringComparison.Ordinal);
        // still a live-status document — the overlay data is present regardless of includeRefresh.
        Assert.Contains("id=\"node-statuses\"", settled, StringComparison.Ordinal);
        Assert.Contains("\"task_root\"", settled, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatuses_EmitsAnOverlayForEachStatusEntry()
    {
        // Every node id in the status map must be referenced by the overlay-rendering logic — the
        // map is embedded as a JSON side-table (mirroring the task-folder-targets side-table) keyed
        // by the SAME Mermaid node/container ids, so the post-render script can position a badge on
        // each matching SVG node. Assert the QUOTED (JSON-key) form: a bare-word check would false-
        // positive on ids like `plan_guardrails` that ALREADY appear in a code comment in today's
        // template — only the emitted status map produces the quoted form.
        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);

        foreach (string nodeId in SampleStatuses.Keys)
        {
            Assert.Contains($"\"{nodeId}\"", live, StringComparison.Ordinal);
        }
    }

    [Fact]
    public void Render_WithRunningStatus_EmitsASpinnerClass_AndSettledStatusesEmitAGlyph()
    {
        // "running" must render an ANIMATED spinner (a CSS @keyframes rotation — no external
        // image/GIF dependency), visibly distinct from a settled status's STATIC glyph (check / X /
        // "?"). Assert both the spinner animation + its dedicated class AND at least one settled
        // glyph are present; the spinner marker (a CSS class) is inherently distinct from the glyph
        // characters, so a spinner can never be mistaken for a settled state.
        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);

        // spinner: a CSS keyframes rotation + a dedicated class (neither exists in the static template).
        Assert.Contains("@keyframes", live, StringComparison.Ordinal);
        Assert.Contains("status-spinner", live, StringComparison.Ordinal);

        // settled glyphs: `passed` -> U+2713 CHECK MARK, `failed` -> U+2717 BALLOT X (both present in
        // SampleStatuses). Escapes, not literal glyphs, keep this source pure-ASCII and unambiguous.
        Assert.Contains("✓", live, StringComparison.Ordinal);
        Assert.Contains("✗", live, StringComparison.Ordinal);
    }
}

